assert len(cases)==12 and len({c['slug'] for c in cases})==12
out=Path('src/demos/life')
for c in cases:
 p=out/c['slug']; p.mkdir(parents=True,exist_ok=True)
 shift=c['id']%3;opts=c['options'][shift:]+c['options'][:shift]
 model={'question':c['q'],'options':opts,'answer':opts.index(c['options'][c['answer']]),'explanation':c['explain']}
 code='''"use client";
import { useRef, useState } from "react";
import { Lesson } from "@/kit/Lesson";
import { Control, Row } from "@/kit/controls";
const model = MODEL;
export default function Demo({slug}:{slug:string}) {
  const [seen,setSeen] = useState([false,false]);
  const seenRef = useRef([false,false]);
  function open(index:0|1, interact:()=>void) {
    if (seenRef.current[index]) return;
    seenRef.current[index] = true;
    setSeen([...seenRef.current]);
    interact();
  }
  return <Lesson slug={slug} predict={{question:model.question,options:model.options,answer:model.answer}} minInteractions={2} exploreHint="Open both panels and compare the evidence." reveal={()=><p>{model.explanation}</p>}>
  {({locked,interact})=><div>
    <svg viewBox="0 0 340 155" className="stage-svg" role="img" aria-label={seen[0] && seen[1] ? model.explanation : "Two ecological evidence panels. Open both to compare."}>
      <rect x="4" y="4" width="154" height="140" rx="12" fill="var(--bg-2)" stroke="var(--line)"/><rect x="182" y="4" width="154" height="140" rx="12" fill="var(--bg-2)" stroke="var(--line)"/>
      <g transform="translate(6 8)">{seen[0] ? <g>LEFT</g> : <text x="75" y="75" textAnchor="middle" fill="var(--muted)" fontSize="14">Panel A</text>}</g>
      <g transform="translate(184 8)">{seen[1] ? <g>RIGHT</g> : <text x="75" y="75" textAnchor="middle" fill="var(--muted)" fontSize="14">Panel B</text>}</g>
    </svg>
    <Row><Control style={{minHeight:44,minWidth:44}} disabled={locked || seen[0]} onClick={()=>open(0,interact)}>Open A</Control><Control style={{minHeight:44,minWidth:44}} disabled={locked || seen[1]} onClick={()=>open(1,interact)}>Open B</Control></Row>
    <p style={{fontSize:"0.8rem",color:"var(--muted)",textAlign:"center",margin:"4px 0"}}>Illustrative scenario</p>
  </div>}
  </Lesson>;
}
'''.replace('MODEL',json.dumps(model,ensure_ascii=False,indent=2)).replace('LEFT',c['left']).replace('RIGHT',c['right'])
 p.joinpath('Demo.tsx').write_text(code)
 ropts=c['recalloptions'][shift:]+c['recalloptions'][:shift]
 recall={'question':c['recallq'],'options':ropts,'answer':ropts.index(c['recalloptions'][0]),'why':c['recallwhy']}
 meta={'slug':c['slug'],'title':c['title'],'hook':c['hook'],'domain':'life','concept':c['slug'],'status':'draft','durationSec':60,'owner':{'categoryManager':'cm-life','builder':'demo-builder'},'learner':{'knows':['Animals depend on features of their surroundings.'],'doesNotKnow':[c['q']]},'misconception':'A single observation or change determines the same outcome everywhere.','objective':c['q'],'claims':[{'id':f"life.{c['slug']}.c1",'text':c['q']+' '+c['explain'],'support':'source','source':c['source'],'status':'unverified'},{'id':f"life.{c['slug']}.c2",'text':'The panels show a simplified illustrative scenario, not observations or measurements of real animals.','support':'convention','source':'Diagram convention','status':'unverified'},{'id':f"life.{c['slug']}.c3",'text':c['recallq']+' '+c['recallwhy'],'support':'source','source':c['source'],'status':'unverified'}],'confidence':'','recall':recall,'evidence':{'qa':[],'simulatedLearner':[],'pairwise':[],'humanLearners':[]},'version':1}
 p.joinpath('meta.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2)+'\n')
Path('company/reviews/zoology-ecology/manifest.json').write_text(json.dumps([{'plan_id':c['id'],'slug':c['slug']} for c in cases],indent=2)+'\n')
print(f'Built {len(cases)} draft animal ecology lessons')
